#!/usr/bin/env julia
# =============================================================================
# make_notebooks.jl -- author the Pluto notebooks of the repository.
#
#   julia --project=. scripts/make_notebooks.jl
#
# The notebooks are deliverables, so they are written by a generator that knows
# Plutos file format exactly (unique cell ids, one `Cell order` section, the
# `@bind` mock for running outside Pluto) instead of by hand. The generated files
# are then plain, editable Pluto notebooks -- and `scripts/validate_notebooks.jl`
# plus `scripts/run_notebooks.jl` check them.
# =============================================================================
#
# The notebooks are deliverables, so they are written by a generator that knows
# Pluto's file format exactly (unique cell ids, one `Cell order` section, the
# `@bind` mock for running outside Pluto) instead of by hand. The generated files
# are then plain, editable Pluto notebooks.
using UUIDs
using Printf

const ROOT = normpath(joinpath(@__DIR__, ".."))
const NOTEBOOKS = joinpath(ROOT, "notebooks")

const BIND_MOCK = raw"""
# This Pluto notebook uses @bind for interactivity. When running this notebook outside of Pluto, the following 'mock version' of @bind gives bound variables a default value (instead of an error).
macro bind(def, element)
    quote
        local iv = try Base.loaded_modules[Base.PkgId(Base.UUID("6e696c72-6542-2067-7265-42206c756150"), "AbstractPlutoDingetjes")].Bonds.initial_value catch; b -> missing; end
        local el = $(esc(element))
        global $(esc(def)) = Core.applicable(Base.get, el) ? Base.get(el) : iv(el)
        el
    end
end
"""

"""One cell: markdown (`md"..."`) or code."""
md_cell(text) = string("md\"\"\"\n", strip(text), "\n\"\"\"")
code_cell(text) = string("begin\n", strip(join("    " .* split(strip(text), "\n"), "\n")),
    "\nend")

"""Write one notebook: header, cells, and the `Cell order` section Pluto expects."""
function write_notebook(name::AbstractString, cells::Vector{String})
    ids = [string(uuid4()) for _ in cells]
    io = IOBuffer()
    print(io, "### A Pluto.jl notebook ###\n# v0.20.23\n\nusing Markdown\nusing InteractiveUtils\n\n",
        BIND_MOCK)
    for (i, cell) in enumerate(cells)
        print(io, "\n# ", Char(0x2554), Char(0x2550), Char(0x2561), " ", ids[i], "\n",
            cell, "\n")
    end
    print(io, "\n# ", Char(0x2554), Char(0x2550), Char(0x2561), " Cell order:\n")
    for id in ids
        print(io, "# ", Char(0x2560), Char(0x2550), id, "\n")
    end
    path = joinpath(NOTEBOOKS, string(name, ".jl"))
    mkpath(NOTEBOOKS)
    write(path, String(take!(io)))
    return path
end

const USINGS = """
using DiscreteSim
using PlutoUI
using Plots
using Statistics
using Printf
using Dates
"""

const HEAD = [md_cell("""
# {TITLE}

{LEAD}

This notebook belongs to the study in this repository: it loads the artefacts the
pipeline produced (`data/analysis.json` and `reports/figures/*.png`), shows the
section of the report it is about, and prints that section to PDF in its last
cell. Nothing here is a copy of a number typed by hand -- every value comes from
the bundle, and the bundle comes from `scripts/run_study.jl`.
"""),
    md_cell("""
## The environment

The first cell activates `notebooks/Project.toml`, which has `DiscreteSim` (this
repository, developed in place) together with `PlutoUI` and `Plots`. Activating it
explicitly means the notebook runs the same environment interactively and headless
(`scripts/run_notebooks.jl`), with no package installation in the middle.
"""),
    code_cell("""
import Pkg
Pkg.activate(@__DIR__)"""),
    code_cell(USINGS),
    code_cell("ROOT = dirname(@__DIR__)"),
    md_cell("""
## The study, loaded from disk

`load_study` reads the JSON the pipeline wrote and turns it back into the
symbol-keyed records the package uses, so the notebook and the printed report
show the same numbers without re-running the study.
"""),
    code_cell("bundle = load_study(ROOT);"),
    code_cell("TableOfContents()")]

const PRINT_CELL = [md_cell("""
## The printout, and its PDF

The cell below writes the section as a self-contained HTML printout and prints it
with a headless browser: `reports/html/notebook_{KEY}.html` and
`reports/pdf/notebook_{KEY}.pdf`. The notebook *is* the report -- the PDF is its
printout.
"""),
    code_cell("""println("run the study first if this file is missing: julia --project=. scripts/run_study.jl")
print_section_pdf(bundle, :{KEY}; root = ROOT)"""),
    ## the closing note is a code cell, not a markdown one: `md"..."` interpolates
    ## everywhere *except* inside a code span, and this note wants the seed inside one
    code_cell("""
Markdown.parse(string("---\\n",
    "*Generated by `DiscreteSim.jl` from `data/analysis.json` (seed `",
    get(get(bundle, :config, SymDict()), :seed, 0),
    "`). Re-run `julia --project=. scripts/run_study.jl` to refresh every number ",
    "in this notebook.*"))""")]

"""Assemble one notebook from its markdown lead, its section key and its middle cells."""
function notebook_of(name, title, lead, key, middle)
    cells = String[]
    for c in HEAD
        push!(cells, replace(c, "{TITLE}" => title, "{LEAD}" => strip(lead)))
    end
    push!(cells, md_cell("## The section: *$(uppercasefirst(replace(string(key), '_' => ' ')))*"))
    push!(cells, code_cell("HTML(preview_section(bundle, :$key))"))
    append!(cells, middle)
    for c in PRINT_CELL
        push!(cells, replace(c, "{KEY}" => string(key)))
    end
    return write_notebook(name, cells)
end

