"""),
    code_cell("""
factor = model_params(:mmc, (arrival_rate = λ, service_rate = 0.5, servers = Int(servers)))
stable = λ / (0.5 * Int(servers)) < 1
study = stable ? experiment(opts -> build_model(:mmc, factor, opts),
